-independent.com/fonts/Independent-Sans-Regular.woff2) format('woff2'); } .bookmark-experience { display: flex; align-items: center; justify-content: center; position: fixed; top: 0; left: 0; width: 100%; height: 100%; background-color: rgba(0, 0, 0, 0.6); z-index: 10000; padding: 20px; } .bookmark-experience * { box-sizing: border-box; } .bookmark-experience .modal { position: relative; background: #e6efee; width: 100%; max-width: 646px; padding: 40px 48px 48px 48px; text-align: center; } .bookmark-experience .close-btn { position: absolute; top: 22px; right: 22px; width: 26px; height: 26px; cursor: pointer; background: none; border: none; padding: 0; } .bookmark-experience .close-btn svg { width: 100%; height: 100%; stroke: #333; stroke-width: 2.2; } .bookmark-experience .logo-row { display: flex; align-items: center; justify-content: center; gap: 12px; margin-bottom: 34px; } .bookmark-experience .logo-icon { width: 34px; height: 34px; flex-shrink: 0; } .bookmark-experience .logo-premium-image { height: 26px; width: auto; } .bookmark-experience .headline { font-family: 'Indy Serif', serif; font-weight: 700; font-size: 32px; line-height: 1.25; color: #0d0d0d; margin: 0 0 26px 0; } .bookmark-experience .body-text { font-family: 'Indy Sans', sans-serif; font-size: 17px; line-height: 1.55; color: #1a1a1a; margin: 0 auto 34px auto; max-width: 480px; } .bookmark-experience .subscribe-link { display: block; text-align: center; font-family: 'Indy Sans', sans-serif; font-size: 17px; font-weight: 700; color: #337F81; text-decoration: underline; cursor: pointer; } .bookmark-experience .subscribe-link:hover { color: #396C6E; } </style> `; document.body.appendChild(modal); modal.addEventListener('click', () => { document.cookie = 'mos-plan-select=; Max-Age=0; path=/; expires=Thu, 01 Jan 1970 00:00:00 UTC;'; }); modal.querySelector('.subscribe-link')?.addEventListener('click', (e) => { e.preventDefault(); document.cookie = 'mos-plan-select=; Max-Age=0; path=/; expires=Thu, 01 Jan 1970 00:00:00 UTC;'; setTimeout(() => { window.location.href = 'https://www.independent.co.uk/subscribe?regSourceMethod=Bookmarks'; }, 500); }); });

